// Paket aufbereiten (runOnceForEachItem): Texte des Entwurfs für die gewählten Kanäle vorbereiten; abgelegt werden sie über SPEICHER 1 (Server oder eigener Speicherort)
const t = $input.item.json;
const arr = v => Array.isArray(v) ? v : [];
const s = v => String(v ?? '').trim();
let p = {};
try { p = typeof t.paket === 'string' ? JSON.parse(t.paket) : (t.paket || {}); } catch (e) { p = {}; }
const kan = arr(p.kanaele).length ? arr(p.kanaele) : ['instagram_post', 'instagram_story', 'linkedin', 'whatsapp'];
const hat = k => kan.includes(k);
// Nur neue/geänderte Kanäle bekommen neue Dateien; veröffentlichte und unveränderte bleiben unangetastet
const info = (($('Entwurf aufbereiten').all().find(i => i.json.id === t.id)) || { json: {} }).json;
const erneuern = arr(info.erneuern);
const entfernt = arr(info.entfernt);
const veroeffentlicht = arr(info.veroeffentlicht);
const neu = k => erneuern.includes(k);

const jetzt = DateTime.now().setZone('Europe/Berlin');
const slugVoll = s(t.titel).toLowerCase().replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
let slug = '';
for (const w of slugVoll.split('-')) { if ((slug ? slug.length + 1 : 0) + w.length > 50) break; slug = slug ? slug + '-' + w : w; }
slug = slug || slugVoll.slice(0, 50) || 'beitrag';
// Rückfall: Standardordner aus dokumente_ordner() über Entwurf speichern (Stefan 18.10.2026)
const basis = s(t.ordner_basis).replace(/\.\./g, '').replace(/[^A-Za-z0-9 _\-\/äöüÄÖÜß]/g, '').replace(/^\/+|\/+$/g, '') || s(t.ordner_standard).replace(/^\/+|\/+$/g, '') || 'Marketing';
// Bestehender Ordner bleibt (Überarbeitung), sonst neu: Monat/Datum_thema-ID_Titel
const alt = s(t.ordner);
const ordner = (alt && !alt.includes('..') && !/["`$\\]/.test(alt) && !alt.includes('/_Verworfen/')) ? alt : basis + '/' + jetzt.toFormat('yyyy-LL') + '/' + jetzt.toFormat('yyyy-LL-dd') + '_thema-' + t.id + '_' + slug;

const folieText = f => {
  const teile = [];
  if (s(f.zahl)) teile.push(s(f.zahl) + (s(f.zahl_label) ? ' ' + s(f.zahl_label) : ''));
  if (s(f.titel)) teile.push(s(f.titel));
  if (s(f.text)) teile.push(s(f.text));
  arr(f.punkte).forEach(x => { const o = typeof x === 'string' ? { text: x } : (x || {}); teile.push('• ' + [s(o.titel), s(o.text)].filter(Boolean).join(': ')); });
  if (f.vorher || f.nachher) { const v = f.vorher || {}, n = f.nachher || {}; teile.push((s(v.label) || 'Vorher') + ': ' + (s(v.text) || s(f.vorher))); teile.push((s(n.label) || 'Nachher') + ': ' + (s(n.text) || s(f.nachher))); }
  return teile.join(' – ').replace(/\*\*/g, '');
};
const NAME = { instagram_post: 'Instagram-Beitrag', instagram_story: 'Instagram-Story', linkedin: 'LinkedIn', whatsapp: 'WhatsApp-Status' };

const rs = p.reel_skript || {};
const md = [];
md.push('# ' + s(t.titel), '');
md.push('Stand: ' + jetzt.toFormat('dd.LL.yyyy HH:mm') + ' · Thema-ID ' + t.id + ' · Kanäle: ' + kan.map(k => NAME[k] || k).join(', '), '');
if (veroeffentlicht.length) md.push('Veröffentlicht (Dateien bleiben unverändert): ' + veroeffentlicht.map(k => NAME[k] || k).join(', '), '');
if (arr(p.pruefen).filter(x => s(x)).length) { md.push('## Vor dem Posten prüfen', ''); arr(p.pruefen).filter(x => s(x)).forEach(x => md.push('- ' + s(x))); md.push(''); }
if (hat('instagram_post')) md.push('## Instagram – Caption', '', s(p.instagram_caption), '', arr(p.instagram_hashtags).map(s).join(' '), '');
if (hat('linkedin')) md.push('## LinkedIn – persönliches Profil', '', s(p.linkedin_profil), '', '## LinkedIn – Seite ' + (($('Themen laden').first().json.firma || {}).name || 'Unternehmen'), '', s(p.linkedin_seite), '');
if (arr(p.karussell).length) { md.push('## Karussell (' + arr(p.karussell).length + ' Folien)', ''); arr(p.karussell).forEach((f, i) => md.push((i + 1) + '. ' + folieText(f || {}))); md.push(''); }
if (arr(p.story).length) { md.push('## Story / Status (' + arr(p.story).length + ' Frames)', ''); arr(p.story).forEach((f, i) => md.push((i + 1) + '. ' + (typeof f === 'string' ? f : folieText(f || {})))); md.push(''); }
if (hat('whatsapp')) md.push('**WhatsApp-Begleittext:** ' + s(p.whatsapp_status), '');
if (rs.hook) { md.push('## Reel-Skript (' + (rs.dauer_sekunden || '?') + ' Sekunden' + (rs.musik_stimmung ? ', Musik: ' + s(rs.musik_stimmung) : '') + ')', '', '**Hook:** ' + s(rs.hook), ''); arr(rs.szenen).forEach((z, i) => md.push('**Szene ' + (i + 1) + '**', '- Bild: ' + s(z.bild), '- Einblendung: ' + s(z.einblendung), '- Sprechtext: ' + s(z.sprechtext), '')); }
if (arr(p.bildideen).filter(x => s(x)).length) { md.push('## Bildideen', ''); arr(p.bildideen).filter(x => s(x)).forEach(x => md.push('- ' + s(x))); md.push(''); }

const q = v => '"' + s(v).replace(/"/g, '""') + '"';
const csv = ['Folie,Typ,Titel,Text'].concat(arr(p.karussell).map((f, i) => (i + 1) + ',' + q(f.typ) + ',' + q(s(f.titel).replace(/\*\*/g, '')) + ',' + q(folieText(Object.assign({}, f, { titel: '' }))))).join('\r\n') + '\r\n';
const storyTexte = arr(p.story).map((f, i) => (i + 1) + '. ' + (typeof f === 'string' ? f : folieText(f || {})));
const dateien = [['beitrag.md', md.join('\n')]];
if (hat('instagram_post') && neu('instagram_post')) { dateien.push(['Instagram-Post/caption.txt', s(p.instagram_caption) + '\n\n' + arr(p.instagram_hashtags).map(s).join(' ') + '\n'], ['Instagram-Post/karussell-canva.csv', '﻿' + csv]); }
if (hat('instagram_story') && neu('instagram_story')) { dateien.push(['Instagram-Story/story-texte.txt', 'Story-Frames (Bilder story-01.jpg ff.):\n\n' + storyTexte.join('\n') + '\n']); }
if (hat('linkedin') && neu('linkedin')) { dateien.push(['LinkedIn/linkedin-profil.txt', s(p.linkedin_profil) + '\n'], ['LinkedIn/linkedin-seite.txt', s(p.linkedin_seite) + '\n']); }
if (hat('whatsapp') && neu('whatsapp')) { dateien.push(['WhatsApp-Status/whatsapp-text.txt', s(p.whatsapp_status) + '\n\nStatus-Bilder: status-01.jpg ff.\n' + storyTexte.join('\n') + '\n']); }
// Nur die Ordner der Kanäle leeren, die neu erzeugt oder ausdrücklich entfernt werden (jeder Kanal hat einen eigenen Unterordner)
const ORDNER = { instagram_post: 'Instagram-Post', instagram_story: 'Instagram-Story', linkedin: 'LinkedIn', whatsapp: 'WhatsApp-Status' };
const alte_ordner = [...new Set(erneuern.concat(entfernt).filter(k => ORDNER[k]).map(k => ordner + '/' + ORDNER[k]))];
const texte = dateien.map(([n, inhalt]) => ({ pfad: ordner + '/' + n, text: inhalt }));

return { json: { id: t.id, titel: s(t.titel), ordner, alte_ordner, texte, paket: JSON.stringify(p), kanaele: kan, erneuern, entfernt, nicht_entfernt: arr(info.nicht_entfernt), veroeffentlicht, linkedin_profil: s(p.linkedin_profil), pruefen: arr(p.pruefen).filter(x => s(x)), folien: arr(p.karussell).length, frames: arr(p.story).length } };

// Folien-Engine v2 für MARKETING 2 – variable Folientypen, Icons, Akzente.
// Eingabe: folien = [{ typ, stil?, titel, text, punkte:[{icon,text}|string], zahl, zahl_label, icon, vorher, nachher }]
// opt: { format: 'post'|'story', cd (Corporate Design aus CD 1), web, absender, icons, gestaltung, hintergruende }
// Eigene Hintergründe (Seite Marketing, Gestaltung): [{ id, hell, src }]; Ally wechselt sie mit den gewählten Folienstilen ab
// Gestaltung je Unternehmen (Seite "Unternehmen"): erlaubte Folienstile, Akzente an/aus, Icons an/aus und abgewählte Icons
function baueFolien(folien, opt) {
  const ICONS = opt.icons || {};
  const G = opt.gestaltung || {};
  const s = v => String(v ?? '').trim();
  // Icons, die die KI für Inhalte wählt, nur wenn eingeschaltet und nicht abgewählt; feste Zeichen (Haken, Pfeil, Kontakt) bleiben
  const ICONS_AUS = Array.isArray(G.icons_aus) ? G.icons_aus : [];
  const frei = name => G.icons !== false && !!ICONS[s(name)] && !ICONS_AUS.includes(s(name));
  const esc = v => s(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const fett = v => esc(v).replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>');
  const story = opt.format === 'story';
  const W = 1080, H = story ? 1920 : 1350;
  const web = opt.web || '';
  const absender = opt.absender || '';
  // Ältere Entwürfe: Story-Frames als Text oder {text} ohne Typ -> als Titel darstellen
  const norm = f => { if (typeof f === 'string') return { titel: f }; if (f && !s(f.typ) && !s(f.titel) && s(f.text) && !(f.punkte || []).length) return Object.assign({}, f, { titel: f.text, text: '' }); return f; };
  const liste = (Array.isArray(folien) ? folien : []).map(norm).filter(f => f && (s(f.titel) || s(f.text) || (f.punkte || []).length || s(f.zahl)));
  const n = liste.length;
  // Farben, Schrift und Logos kommen zentral aus CD 1 (Seite "Unternehmen")
  const CD = opt.cd;
  const A = CD.abgeleitet;
  const L = CD.logos;
  const C = { dunkel: CD.farben.dunkel, salbei: CD.farben.akzent, grau: CD.farben.grau, hell: CD.farben.hell, weiss: CD.farben.textAufDunkel, salbeiDunkel: CD.farben.akzentDunkel };
  const dunkelRgba = a => 'rgba(' + [1, 3, 5].map(k => parseInt(C.dunkel.slice(k, k + 2), 16)).join(',') + ',' + a + ')';

  const icon = (name, groesse, farbe, breite) => {
    const inner = ICONS[s(name)] || '';
    if (!inner) return '';
    return `<svg xmlns="http://www.w3.org/2000/svg" width="${groesse}" height="${groesse}" viewBox="0 0 24 24" fill="none" stroke="${farbe}" stroke-width="${breite || 1.75}" stroke-linecap="round" stroke-linejoin="round">${inner}</svg>`;
  };

  // Stil je Folie: explizit oder abwechslungsreich nach Typ (nie zweimal derselbe automatisch hintereinander).
  // Nur erlaubte Stile; "akzent" in den Einstellungen heißt hier "salbei" (Hintergrund in der Akzentfarbe).
  const ERL0 = (Array.isArray(G.stile) ? G.stile : []).map(x => x === 'akzent' ? 'salbei' : x).filter(x => ['dunkel', 'hell', 'salbei'].includes(x));
  const ERL = ERL0.length ? ERL0 : ['dunkel', 'hell', 'salbei'];
  const ersatz = { dunkel: ['salbei', 'hell'], hell: ['salbei', 'dunkel'], salbei: ['dunkel', 'hell'] };
  const passend = w => ERL.includes(w) ? w : (ersatz[w].find(x => ERL.includes(x)) || ERL[0]);
  const stile = [];
  liste.forEach((f, i) => {
    const st = s(f.stil).toLowerCase();
    if (['dunkel', 'hell', 'salbei'].includes(st) && ERL.includes(st)) { stile.push(st); return; }
    const t = s(f.typ).toLowerCase();
    let w = passend((i === 0 || t === 'titel' || t === 'abschluss') ? 'dunkel' : (t === 'aussage' || t === 'zitat' || t === 'zahl') ? 'salbei' : 'hell');
    const vor = stile[i - 1];
    if (vor === w) w = ERL.find(x => x !== w && x === (w === 'hell' ? 'dunkel' : 'hell')) || ERL.find(x => x !== w) || w;
    stile.push(w);
  });
  const autoStil = (f, i) => stile[i];
  // Eigene Hintergründe: ohne gewählten Folienstil auf allen Folien, sonst auf jeder zweiten (beginnend mit der ersten).
  // Eine von der KI ausdrücklich gewählte Farbe (stil) hat Vorrang.
  const HG = (Array.isArray(opt.hintergruende) ? opt.hintergruende : []).filter(h => h && /^data:image\/(jpeg|png);base64,[A-Za-z0-9+/]+={0,2}$/.test(String(h.src || '')));
  const nurBild = HG.length > 0 && Array.isArray(G.stile) && ERL0.length === 0;
  let hgZaehler = 0;
  const bildVon = liste.map((f, i) => {
    if (!HG.length) return -1;
    if (!nurBild && (i % 2 !== 0 || ['dunkel', 'hell', 'salbei'].includes(s(f.stil).toLowerCase()))) return -1;
    return (hgZaehler++) % HG.length;
  });
  const rgbaVon = (hex, a) => 'rgba(' + [1, 3, 5].map(k => parseInt(String(hex).slice(k, k + 2), 16)).join(',') + ',' + a + ')';
  const farben = st => st === 'hell'
    ? { bg: C.hell, text: C.dunkel, neben: A.hellNebentext, akzent: C.salbeiDunkel, linie: A.hellLinie, karte: '#FFFFFF', kartenRand: A.hellKartenrand, iconBg: C.dunkel, iconFg: C.salbei, logo: L.bildmarke_fuer_hell, logoKachel: false }
    : st === 'salbei'
      ? { bg: C.salbei, text: C.dunkel, neben: A.akzentNebentext, akzent: C.dunkel, linie: dunkelRgba(.18), karte: 'rgba(255,255,255,.35)', kartenRand: dunkelRgba(.12), iconBg: C.dunkel, iconFg: C.salbei, logo: L.bildmarke_fuer_dunkel, logoKachel: true }
      : { bg: C.dunkel, text: C.weiss, neben: A.dunkelNebentext, akzent: C.salbei, linie: A.dunkelLinie, karte: A.dunkelKarte, kartenRand: A.dunkelKartenrand, iconBg: C.salbei, iconFg: C.dunkel, logo: L.bildmarke_fuer_dunkel, logoKachel: false };

  // Dekorationen (abwechselnd, dezent)
  const deko = (st, i, f) => {
    const F = farben(st);
    const v = i % 3;
    const punkte = G.punkte === false ? '' : `<div class="punkte" style="background-image: radial-gradient(${F.akzent} 2.2px, transparent 2.4px); opacity:${st === 'hell' ? .22 : .18}"></div>`;
    const boegen = G.boegen === false ? '' : `<svg class="boegen" width="760" height="760" viewBox="0 0 760 760"><circle cx="560" cy="200" r="300" fill="none" stroke="${F.akzent}" stroke-opacity=".22" stroke-width="2"/><circle cx="560" cy="200" r="220" fill="none" stroke="${F.akzent}" stroke-opacity=".14" stroke-width="2"/><circle cx="560" cy="200" r="140" fill="none" stroke="${F.akzent}" stroke-opacity=".10" stroke-width="2"/></svg>`;
    const grossIcon = G.gross_icon !== false && frei(f.icon) ? `<div class="gross-icon">${icon(f.icon, story ? 760 : 620, F.akzent, 1.1)}</div>` : '';
    if (v === 0) return punkte + grossIcon;
    if (v === 1) return boegen || punkte;
    return grossIcon || punkte;
  };

  // Bildmarke passend zum Hintergrund; auf Salbei steht sie in einer dunklen Kachel, weil ihr gruener Teil sonst verschwindet
  const marke = F => F.logoKachel ? `<div class="logo-kachel" style="background:${C.dunkel}"><img src="${F.logo}" alt=""></div>` : `<img class="logo" src="${F.logo}" alt="">`;
  const kopf = (i, F) => `<div class="kopf">${marke(F)}<div class="nr" style="color:${F.akzent}">${String(i + 1).padStart(2, '0')}<span style="color:${F.neben};opacity:.55"> / ${String(n).padStart(2, '0')}</span></div></div>`;
  const fuss = (i, F) => `<div class="fuss" style="border-color:${F.linie};color:${F.neben}"><div><b style="color:${F.text}">${esc(absender)}</b></div><div style="color:${F.akzent};font-weight:700">${esc(web)}</div></div>`
    + (n > 1 ? `<div class="fortschritt">${liste.map((_, k) => `<span style="background:${k <= i ? F.akzent : F.linie}"></span>`).join('')}</div>` : '');
  const punkteListe = f => (Array.isArray(f.punkte) ? f.punkte : []).map(p => typeof p === 'string' ? { text: p } : (p || {})).filter(p => s(p.text) || s(p.titel));

  const koerper = (f, i, F) => {
    const t = s(f.typ).toLowerCase() || (i === 0 ? 'titel' : (i === n - 1 && n > 1 ? 'abschluss' : 'text'));
    const titel = s(f.titel) ? `<h2>${fett(f.titel)}</h2>` : '';
    const text = s(f.text) ? `<p class="text" style="color:${F.neben}">${fett(f.text)}</p>` : '';
    const pk = punkteListe(f);
    if (t === 'titel') {
      return `<div class="inhalt titel">${frei(f.icon) ? `<div class="icon-kachel" style="background:${F.iconBg}">${icon(f.icon, 64, F.iconFg, 2)}</div>` : '<div class="strich" style="background:' + F.akzent + '"></div>'}<h1>${fett(f.titel)}</h1>${text}${n > 1 && !story ? `<div class="weiter" style="color:${F.akzent}">Wischen ${icon('arrow-right', 40, F.akzent, 2.2)}</div>` : ''}</div>`;
    }
    if (t === 'aussage' || t === 'zitat') {
      return `<div class="inhalt aussage"><div class="anf" style="color:${F.akzent}">“</div><h2 class="gross">${fett(f.titel || f.text)}</h2>${f.titel && f.text ? text : ''}</div>`;
    }
    if (t === 'zahl') {
      return `<div class="inhalt zahl"><div class="zahl-gross" style="color:${F.akzent}">${esc(f.zahl || f.titel)}</div>${s(f.zahl_label) ? `<div class="zahl-label">${fett(f.zahl_label)}</div>` : ''}${s(f.zahl) && s(f.titel) ? titel : ''}${text}</div>`;
    }
    if (t === 'liste') {
      return `<div class="inhalt liste">${titel}${text}<div class="karten">${pk.map(p => `<div class="karte" style="background:${F.karte};border-color:${F.kartenRand}"><div class="icon-kachel klein" style="background:${F.iconBg}">${icon(frei(p.icon) ? p.icon : frei(f.icon) ? f.icon : 'check', 40, F.iconFg, 2)}</div><div>${s(p.titel) ? `<div class="k-titel">${fett(p.titel)}</div>` : ''}<div class="k-text" style="color:${s(p.titel) ? F.neben : F.text}">${fett(p.text)}</div></div></div>`).join('')}</div></div>`;
    }
    if (t === 'schritte') {
      return `<div class="inhalt schritte">${titel}${text}<div class="stufen">${pk.map((p, k) => `<div class="stufe"><div class="kreis" style="border-color:${F.akzent};color:${F.akzent}">${k + 1}</div>${k < pk.length - 1 ? `<div class="verbinder" style="background:${F.linie}"></div>` : ''}<div>${s(p.titel) ? `<div class="k-titel">${fett(p.titel)}</div>` : ''}<div class="k-text" style="color:${s(p.titel) ? F.neben : F.text}">${fett(p.text)}</div></div></div>`).join('')}</div></div>`;
    }
    if (t === 'checkliste') {
      return `<div class="inhalt checkliste">${titel}${text}<div class="checks">${pk.map(p => `<div class="check"><span class="haken" style="background:${F.akzent}">${icon('check', 34, F.bg, 3)}</span><span>${fett(p.text || p.titel)}</span></div>`).join('')}</div></div>`;
    }
    if (t === 'vergleich') {
      const sp = (k, lbl, ic, inhalt, hervor) => `<div class="spalte" style="background:${hervor ? F.akzent : F.karte};border-color:${F.kartenRand};color:${hervor ? (F.bg === C.salbei ? C.weiss : C.dunkel) : F.text}"><div class="sp-kopf">${icon(ic, 40, hervor ? (F.bg === C.salbei ? C.weiss : C.dunkel) : F.neben, 2.2)}<span>${esc(lbl)}</span></div><div class="sp-text">${fett(inhalt)}</div></div>`;
      const v = f.vorher || {}, nn = f.nachher || {};
      return `<div class="inhalt vergleich">${titel}<div class="spalten">${sp(0, s(v.label) || 'Vorher', 'circle-x', s(v.text) || s(f.vorher), false)}${sp(1, s(nn.label) || 'Nachher', 'circle-check', s(nn.text) || s(f.nachher), true)}</div>${text}</div>`;
    }
    if (t === 'abschluss') {
      return `<div class="inhalt abschluss">${frei(f.icon) ? `<div class="icon-kachel" style="background:${F.iconBg}">${icon(f.icon, 64, F.iconFg, 2)}</div>` : ''}${titel}${text}<div class="kontakt" style="border-color:${F.akzent}"><div>${icon('message-circle', 44, F.akzent, 2)}<span>Schreib uns eine Nachricht</span></div><div>${icon('globe', 44, F.akzent, 2)}<span style="color:${F.akzent}">${esc(web)}</span></div></div></div>`;
    }
    // text (Standard): Titel + Text, optional Icon-Kachel
    return `<div class="inhalt text-folie">${frei(f.icon) ? `<div class="icon-kachel" style="background:${F.iconBg}">${icon(f.icon, 56, F.iconFg, 2)}</div>` : ''}${titel}${text}</div>`;
  };

  const css = `
  ${opt.fontCss || ''}
  @page { size: ${W}px ${H}px; margin: 0; }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body { width:${W}px; height:${H}px; }
  body { font-family: '${CD.schrift}', sans-serif; -webkit-font-smoothing: antialiased; font-feature-settings: 'lnum' 1; }
  .folie { width:${W}px; height:${H}px; position: relative; overflow: hidden; display: flex; flex-direction: column; padding: ${story ? '150px 100px 0' : '88px 96px 0'}; }
  .punkte { position:absolute; right:-40px; top:-40px; width:520px; height:520px; background-size: 34px 34px; -webkit-mask-image: radial-gradient(circle at 70% 30%, #000 0%, transparent 70%); }
  .boegen { position:absolute; right:-300px; bottom:-120px; }
  .gross-icon { position:absolute; right:-150px; bottom:${story ? 260 : 130}px; opacity:.07; transform: rotate(-12deg); }
  .kopf { position: relative; z-index: 2; display:flex; align-items:center; justify-content:space-between; height:72px; }
  .kopf img.logo { height:56px; width:auto; display:block; }
  .logo-kachel { height:72px; padding:0 16px; border-radius:14px; display:flex; align-items:center; }
