const RENDER = 'http://ally-render:3000';
// Corporate Design (Schrift, Farben, Logos, Gestaltung, Icons) aus CD 1
const CD = $('Corporate Design (CD 1)').first().json;
const self = this;
const ascii = x => { let o = ''; for (const ch of x) { const c = ch.codePointAt(0); o += c < 128 ? ch : '&#' + c + ';'; } return o; };
async function rendern(route, html, felder) {
  // Multipart als reiner ASCII-Text (Umlaute als HTML-Entities), da Buffer-Bodies im Code-Node nicht sauber übertragen werden
  const grenze = '----ally' + Date.now().toString(16) + Math.random().toString(16).slice(2);
  let body = '';
  for (const [k, v] of Object.entries(felder)) body += '--' + grenze + '\r\nContent-Disposition: form-data; name="' + k + '"\r\n\r\n' + v + '\r\n';
  body += '--' + grenze + '\r\nContent-Disposition: form-data; name="files"; filename="index.html"\r\nContent-Type: text/html\r\n\r\n' + ascii(html) + '\r\n--' + grenze + '--\r\n';
  const antwort = await self.helpers.httpRequest({
    method: 'POST', url: RENDER + route, body,
    headers: { 'Content-Type': 'multipart/form-data; boundary=' + grenze },
    encoding: 'arraybuffer', json: false, timeout: 90000, returnFullResponse: true, ignoreHttpStatusErrors: true
  });
  const daten = Buffer.from(antwort.body);
  if (antwort.statusCode !== 200) throw new Error('Render-Dienst ' + antwort.statusCode + ': ' + daten.toString('utf8').slice(0, 250));
  return daten;
}

