const abl = {}; for (const i of $('Grafiken ablegen (SPEICHER 1)').all()) if (i.json.aktion === 'ablegen') abl[i.json.pfad] = i.json;
const entwuerfe = $('Paket aufbereiten').all().map(i => {
  let p = {};
  try { p = JSON.parse(i.json.paket); } catch (e) { p = {}; }
  const eigene = gr.map(g => ({ g, a: abl[g.ordner + '/' + g.datei] || {} })).filter(x => x.g.id === i.json.id);
  return {
    thema_id: i.json.id, titel: i.json.titel, ablage: i.json.ordner, kanaele: arr(p.kanaele),
    neu_erzeugt: arr(i.json.erneuern), unveraendert: arr(p.kanaele).filter(k => !arr(i.json.erneuern).includes(k)), veroeffentlicht: arr(i.json.veroeffentlicht), entfernt: arr(i.json.entfernt), nicht_entfernt_weil_veroeffentlicht: arr(i.json.nicht_entfernt),
    grafiken: eigene.filter(x => x.g.ok && x.a.ok === true).length,
    grafik_fehler: eigene.filter(x => !x.g.ok || x.a.ok !== true).map(x => (x.g.datei || '') + ': ' + (x.g.fehler || x.a.fehler || 'unbekannt')),
    vor_dem_posten_pruefen: arr(p.pruefen)
  };
});
return [{ json: {
  status: 'Entwurf erstellt bzw. ergänzt und als Dateien im Ordner abgelegt (Speicherort: ' + ort + ') (nur neu_erzeugt-Kanäle wurden neu geschrieben, die übrigen blieben unverändert). Kurzinfo (Ordner, Anzahl) und die Texte (Caption / LinkedIn / WhatsApp) wurden dem Nutzer bereits im Chat geschickt. Noch NICHT freigegeben.',
  anweisung_fuer_ally: 'Nichts davon wiederholen. Antworte nur kurz: ggf. grafik_fehler nennen, ggf. die Punkte aus vor_dem_posten_pruefen als Frage, dann "Schau dir die Bilder im Ordner an – passt das so, oder was soll ich ändern?"',
  entwuerfe
} }];

parameters.query:
WITH ids AS (
  SELECT x::int AS id FROM regexp_split_to_table(coalesce($2::text, ''), '[^0-9]+') AS x WHERE x <> ''
), alt AS (
  SELECT m.id, m.titel, m.ordner FROM marketing_themen m JOIN ids ON ids.id = m.id WHERE m.matrix_user_id = $1::text
), st AS (
  UPDATE marketing_posts p SET status = 'storniert', geaendert_am = now()
  WHERE p.thema_id IN (SELECT id FROM alt) AND p.status = 'freigegeben' RETURNING p.id
), upd AS (
  UPDATE marketing_themen m SET status = 'verworfen',
    ordner = CASE WHEN alt.ordner IS NULL THEN NULL ELSE regexp_replace(alt.ordner, '^(.*)/[0-9]{4}-[0-9]{2}/([^/]+)$', '\1/_Verworfen/\2') END,
    geaendert_am = now()
  FROM alt WHERE m.id = alt.id RETURNING m.id, m.ordner AS neu
)
SELECT alt.id, alt.titel, alt.ordner AS alt, upd.neu, (SELECT count(*) FROM st) AS stornierte_posts
FROM alt JOIN upd ON upd.id = alt.id ORDER BY alt.id;

parameters.jsCode:
// Verschieben vorbereiten: Themenordner nach _Verworfen verschieben (Aufträge an SPEICHER 1, nichts überschreiben).
// Ohne Ordner nur eine Prüfung des Platzhalters "_", damit der Ablauf weiterläuft.
const auftraege = $input.all().map(i => i.json)
  .filter(j => String(j.alt || '').trim() && String(j.neu || '').trim() && String(j.alt).trim() !== String(j.neu).trim())
  .map(j => ({ json: { aktion: 'verschieben', pfad: String(j.alt).trim(), ziel_pfad: String(j.neu).trim(), ueberschreiben: false } }));
return auftraege.length ? auftraege : [{ json: { aktion: 'pruefen', pfad: '_' } }];

const rows = $('Verwerfen').all().map(i => i.json).filter(r => r.id);
const erg = {}; for (const i of $('Verwerfen (SPEICHER 1)').all()) if (i.json.aktion === 'verschieben') erg[i.json.pfad] = i.json;
if (!rows.length) return [{ json: { status: 'Nichts verworfen', fehler: 'Thema nicht gefunden.' } }];
return [{ json: { status: 'Verworfen', themen: rows.map(r => ({ thema_id: r.id, titel: r.titel, ordner: r.alt ? ((erg[r.alt] || {}).ok ? 'verschoben nach ' + r.neu : 'nicht verschoben' + ((erg[r.alt] || {}).fehler ? ': ' + erg[r.alt].fehler : '')) : 'es gab noch keinen Ordner', stornierte_posts: Number(r.stornierte_posts || 0) })) } }];

// Chat-Layout (Vorgabe Stefan, 11.10.2026): Titel fett mit Doppelpunkt, Inhalt direkt darunter, Leerzeile zwischen Bloecken, keine Listenpunkte, keine Emojis
const esc = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '').split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const roh = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '');
const zeileHtml = z => typeof z === 'string' ? esc(z) : (z.html !== undefined ? z.html : (z.kursiv ? '<em>' + esc(z.t) + '</em>' : esc(z.t)));
const zeileText = z => typeof z === 'string' ? roh(z) : (z.behalten ? String(z.t ?? '') : roh(z.t));
const render = bloecke => {
  const b = bloecke.filter(x => x && (x.titel || (x.zeilen || []).length));
  return {
    html: b.map(x => (x.titel ? '<strong>' + esc(x.titel) + '</strong>' + ((x.zeilen || []).length ? '<br>' : '') : '') + (x.zeilen || []).map(zeileHtml).join('<br>')).join('<br><br>'),
    text: b.map(x => (x.titel ? roh(x.titel) + ((x.zeilen || []).length ? '\n' : '') : '') + (x.zeilen || []).map(zeileText).join('\n')).join('\n\n')
  };
};
// Entwurf-Nachricht bauen: Kurzinfo + Texte der gewählten Kanäle (je eine Nachricht)
const s = v => String(v ?? '').trim();
const arr = v => Array.isArray(v) ? v : [];
const nutzer = s(($('Final?').first().json || {}).nutzer);
const gr = $('Grafiken filtern').all().map(i => i.json);
const abl = {}; for (const i of $('Grafiken ablegen (SPEICHER 1)').all()) if (i.json.aktion === 'ablegen') abl[i.json.pfad] = i.json;
// Beitragstexte zeilengetreu (Leerzeilen bleiben), Emojis im Beitrag bleiben erhalten
const textZeilen = v => s(v).split('\n').map(z => ({ t: z, behalten: true, html: String(z).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;') }));
const raus = [];
for (const it of $('Paket aufbereiten').all()) {
  const j = it.json;
  let p = {};
  try { p = JSON.parse(j.paket); } catch (e) { p = {}; }
  const kan = arr(p.kanaele);
  const er = arr(j.erneuern), vf = arr(j.veroeffentlicht);
  const NAME = { instagram_post: 'Instagram-Beitrag', instagram_story: 'Instagram-Story', linkedin: 'LinkedIn', whatsapp: 'WhatsApp-Status' };
  const bleibt = k => NAME[k] + ': unverändert' + (vf.includes(k) ? ' (veröffentlicht)' : '');
  const eigene = gr.map(g => ({ g, a: abl[g.ordner + '/' + g.datei] || {} })).filter(x => x.g.id === j.id);
  const ok = eigene.filter(x => x.g.ok && x.a.ok === true).map(x => String(x.g.datei));
  const fehler = eigene.filter(x => !x.g.ok || x.a.ok !== true).map(x => (x.g.datei === '(Hinweis)' ? '' : x.g.datei + ': ') + (x.g.fehler || x.a.fehler || 'unbekannt'));
  const n = pre => ok.filter(d => d.startsWith(pre)).length;
  const zeilen = [];
  if (kan.includes('instagram_post')) zeilen.push(er.includes('instagram_post') ? 'Instagram-Beitrag: ' + n('Instagram-Post/') + (n('Instagram-Post/') === 1 ? ' Bild' : ' Folien') + ' + Caption' : bleibt('instagram_post'));
  if (kan.includes('instagram_story')) zeilen.push(er.includes('instagram_story') ? 'Instagram-Story: ' + n('Instagram-Story/') + ' Frames' : bleibt('instagram_story'));
  if (kan.includes('linkedin')) zeilen.push(er.includes('linkedin') ? 'LinkedIn: Text' + (n('LinkedIn/') ? ' + PDF mit ' + arr(p.karussell).length + ' Seiten' : '') : bleibt('linkedin'));
  if (kan.includes('whatsapp')) zeilen.push(er.includes('whatsapp') ? 'WhatsApp-Status: ' + n('WhatsApp-Status/') + ' Bilder + Text' : bleibt('whatsapp'));
  arr(j.entfernt).forEach(k => zeilen.push((NAME[k] || k) + ': entfernt'));
  arr(j.nicht_entfernt).forEach(k => zeilen.push((NAME[k] || k) + ': nicht entfernt, bereits veröffentlicht'));
  raus.push(render([
    { titel: 'Entwurf zu Thema ' + j.id + ':', zeilen: [s(j.titel).replace(/\*\*/g, '')] },
    { titel: 'Ordner:', zeilen: [{ t: j.ordner, html: '<code>' + esc(j.ordner) + '</code>' }] },
    { titel: 'Kanäle:', zeilen },
    fehler.length ? { titel: 'Hinweis:', zeilen: fehler } : null
  ]));
  if (kan.includes('instagram_post') && s(p.instagram_caption) && er.includes('instagram_post')) raus.push(render([{ titel: 'Instagram-Caption:', zeilen: textZeilen(p.instagram_caption) }, { titel: 'Hashtags:', zeilen: [{ t: arr(p.instagram_hashtags).join(' '), kursiv: true }] }]));
  if (kan.includes('linkedin') && s(p.linkedin_profil) && er.includes('linkedin')) raus.push(render([{ titel: 'LinkedIn-Text:', zeilen: textZeilen(p.linkedin_profil) }]));
  if (kan.includes('whatsapp') && s(p.whatsapp_status) && er.includes('whatsapp')) raus.push(render([{ titel: 'WhatsApp-Begleittext:', zeilen: textZeilen(p.whatsapp_status) }]));
}
return raus.map(r => ({ json: Object.assign({ user_id: nutzer }, r) }));

// Grafiken filtern: nur Grafiken der neu erzeugten Kanäle behalten (veröffentlichte/unveränderte bleiben unangetastet); Story-Bilder für WhatsApp-Status zusätzlich ablegen
const erVon = {};
for (const it of $('Paket aufbereiten').all()) erVon[it.json.id] = Array.isArray(it.json.erneuern) ? it.json.erneuern : [];
const raus = [];
for (const it of $input.all()) {
  const j = it.json;
  const er = erVon[j.id] || [];
  const d = String(j.datei || '');
  if (d === '(Hinweis)' || !j.id) { if (er.length) raus.push(it); continue; }
  if (d.startsWith('Instagram-Post/')) { if (er.includes('instagram_post')) raus.push(it); continue; }
  if (d.startsWith('LinkedIn/')) { if (er.includes('linkedin')) raus.push(it); continue; }
  if (d.startsWith('Instagram-Story/')) {
    if (er.includes('instagram_story')) raus.push(it);
    if (er.includes('whatsapp')) {
      const name = d.replace('Instagram-Story/story-', 'status-');
      const bin = it.binary && it.binary.datei ? { datei: Object.assign({}, it.binary.datei, { fileName: name }) } : undefined;
      raus.push({ json: Object.assign({}, j, { datei: 'WhatsApp-Status/' + name }), binary: bin });
    }
    continue;
  }
  raus.push(it);
}
// Nichts neu zu erzeugen: Platzhalter ohne Thema-ID, wird in den Meldungen ignoriert
return raus.length ? raus : [{ json: { id: null, datei: '(keine)', ok: true, skip: true } }];

parameters.query:
UPDATE marketing_themen m SET status = 'fertig', geaendert_am = now()
WHERE m.id IN (SELECT x::int FROM json_array_elements_text($1::json) AS x) AND m.ordner IS NOT NULL
RETURNING m.id, m.titel, m.ordner;

parameters.jsCode:
const rows = $('Freigeben').all().map(i => i.json).filter(r => r.id);
if (!rows.length) return [{ json: { status: 'Nicht freigegeben', fehler: 'Zu dieser thema_id gibt es keinen Entwurf mit Dateien.' } }];
return [{ json: { status: 'Freigegeben – kann jetzt gepostet werden (Beitrag zum Posten freigeben)', themen: rows.map(r => ({ thema_id: r.id, titel: r.titel, ablage: r.ordner })) } }];

// Alte Dateien vorbereiten: Kanal-Ordner leeren, die neu erzeugt oder entfernt werden (Aufträge an SPEICHER 1).
// Gibt es nichts zu leeren, prüft der Aufruf nur einen nicht vorhandenen Platzhalter "_", damit der Ablauf weiterläuft.
const auftraege = [];
for (const it of $('Paket aufbereiten').all()) for (const p of (it.json.alte_ordner || [])) auftraege.push({ json: { aktion: 'loeschen', pfad: p } });
return auftraege.length ? auftraege : [{ json: { aktion: 'pruefen', pfad: '_' } }];

// Texte vorbereiten: Ergebnis des Leerens prüfen, dann Beitragstexte als Aufträge an SPEICHER 1 (je Datei ein Item)
const fehler = $input.all().map(i => i.json).filter(r => r.ok === false).map(r => r.fehler);
if (fehler.length) throw new Error('Alte Entwurfsdateien konnten nicht entfernt werden: ' + fehler.join(' '));
const auftraege = [];
for (const it of $('Paket aufbereiten').all()) for (const t of (it.json.texte || [])) auftraege.push({ json: { aktion: 'ablegen', pfad: t.pfad, text: t.text } });
return auftraege;

// Texte geprüft: Bricht ab, wenn ein Text nicht abgelegt werden konnte (wie bisher stoppt der Ablauf mit Fehlermeldung)
const fehler = $input.all().map(i => i.json).filter(r => r.ok !== true).map(r => r.fehler || ('Unbekannter Fehler bei ' + r.pfad));
if (fehler.length) throw new Error('Entwurfstexte konnten nicht abgelegt werden: ' + fehler.join(' '));
return $input.all().map(i => ({ json: { ok: true, pfad: i.json.pfad } }));

// Grafiken vorbereiten: erzeugte Grafiken als Aufträge an SPEICHER 1 (Pfad = Themenordner/Kanal/Datei).
// Ohne Grafiken nur eine Prüfung des Platzhalters "_", damit der Ablauf weiterläuft.
const auftraege = $input.all()
  .filter(it => it.json.id && it.json.ok && it.binary && it.binary.datei && it.json.ordner && it.json.datei)
  .map(it => ({ json: { aktion: 'ablegen', pfad: it.json.ordner + '/' + it.json.datei }, binary: { datei: it.binary.datei } }));
return auftraege.length ? auftraege : [{ json: { aktion: 'pruefen', pfad: '_' } }];

// KI-Budget-Sperre (Stefan 18.10.2026): Nachricht an die Person, die den Beitrag angefordert hat (Chat-Layout wie Entwurf-Nachricht bauen, keine Emojis)
const esc = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '').split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const roh = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '');
const themen = $('Themen laden').all().map(i => i.json);
const grund = String((themen[0] || {}).ki_sperre_text || '').trim() || 'Das KI-Budget für diesen Monat ist erreicht.';
const zeilen = themen.map(t => String(t.titel || 'Thema ' + t.id).replace(/\*\*/g, '').trim());
const titel = zeilen.length > 1 ? 'Beiträge nicht erstellt:' : 'Beitrag nicht erstellt:';
const text = roh(titel) + (zeilen.length ? '\n' + zeilen.map(roh).join('\n') : '') + '\n\nGrund:\n' + roh(grund);
const html = '<strong>' + esc(titel) + '</strong>' + (zeilen.length ? '<br>' + zeilen.map(esc).join('<br>') : '') + '<br><br><strong>Grund:</strong><br>' + esc(grund);
return [{ json: { user_id: String(($('Final?').first().json || {}).nutzer || '').trim(), text, html, grund } }];

// Ergebnis fuer Ally bzw. ALLY 13 bei KI-Budget-Sperre (Stefan 18.10.2026): nichts erzeugt, Grund wurde bereits in den Chat geschickt
const grund = String($('Sperre-Nachricht bauen').first().json.grund || '').trim();
return [{ json: { status: 'Nichts erzeugt', fehler: grund, anweisung_fuer_ally: 'Der Grund wurde dem Nutzer bereits im Chat geschickt. Nicht wiederholen.' } }];
